begin read only; set local statement_timeout='5s'; with ids as materialized (select c.fabric_id from curtainsuk_private.fabric_colourways c join curtainsuk_private.browse_read_projection p on p.fabric_id=c.fabric_id and p.generation_id=(select active_generation from curtainsuk_private.browse_projection_control where singleton) where c.storefront_selectable and c.staging_catalog_visible and c.lifecycle_state<>'DISCONTINUED' and c.price_verification_status='VERIFIED' order by c.fabric_id limit 20000) select jsonb_build_object('observed_at',clock_timestamp(),'projectRef','hqysjumypgeapgmqkcrx','classification','CANDIDATE_IDS_NOT_LIVE_PUBLICATION_PROOF','identity_count',count(*),'identity_sha256',encode(sha256(convert_to(string_agg(fabric_id,E'\n' order by fabric_id),'UTF8')),'hex'),'ids',jsonb_agg(fabric_id order by fabric_id),'generation',(select active_generation from curtainsuk_private.browse_projection_control where singleton),'prepared_count',(select count(*) from curtainsuk_private.browse_read_projection where generation_id=(select active_generation from curtainsuk_private.browse_projection_control where singleton))) as manifest from ids; commit;
